/**
 * SparseSet: dense array + entity->dense-index map.
 *
 * - `sparse` is indexed by entity id and stores the entity's position in
 *   `dense` (or NO_INDEX if absent). It grows lazily so memory scales with
 *   the max entity id actually seen, not a fixed cap.
 * - `dense` packs live entities (and their component payloads, kept by the
 *   owner) contiguously -> cache-friendly iteration.
 *
 * All operations are O(1): add (append), remove (swap-with-last), has, get
 * index. Iteration order is unspecified but stable between mutations.
 */
export const NO_INDEX = -1;

export class SparseSet {
  /** entity id -> dense index */
  private sparse: Int32Array;
  /** dense index -> entity id (packed) */
  readonly dense: number[] = [];

  constructor(initialCapacity = 1024) {
    this.sparse = new Int32Array(initialCapacity).fill(NO_INDEX);
  }

  get size(): number {
    return this.dense.length;
  }

  private ensure(entityId: number): void {
    if (entityId >= this.sparse.length) {
      // grow to next power of two >= entityId + 1
      let cap = this.sparse.length;
      while (cap <= entityId) cap *= 2;
      const next = new Int32Array(cap).fill(NO_INDEX);
      next.set(this.sparse);
      this.sparse = next;
    }
  }

  has(entityId: number): boolean {
    return (
      entityId < this.sparse.length &&
      this.sparse[entityId] !== NO_INDEX &&
      this.dense[this.sparse[entityId]] === entityId
    );
  }

  indexOf(entityId: number): number {
    if (entityId >= this.sparse.length) return NO_INDEX;
    const idx = this.sparse[entityId];
    return idx !== NO_INDEX && this.dense[idx] === entityId ? idx : NO_INDEX;
  }

  add(entityId: number): void {
    if (this.has(entityId)) return;
    this.ensure(entityId);
    this.sparse[entityId] = this.dense.length;
    this.dense.push(entityId);
  }

  /** O(1): swap the removed slot with the last element. */
  remove(entityId: number): void {
    const idx = this.indexOf(entityId);
    if (idx === NO_INDEX) return;
    const last = this.dense.length - 1;
    const swapped = this.dense[last];
    this.dense[idx] = swapped;
    this.sparse[swapped] = idx;
    this.dense.pop();
    this.sparse[entityId] = NO_INDEX;
  }
}

