import { NO_INDEX, SparseSet } from "./sparse-set.js";

/** Minimal archetype-free component storage: one SparseSet + SoA payload per component. */
export interface ComponentStore<T> {
  set: SparseSet;
  data: T[]; // parallel to store.dense; dense[i] holds data for entity store.dense[i]
}

export class World {
  private nextEntity = 0;
  /** live entities, packed for iteration */
  readonly entities: number[] = [];
  private entityIndex = new Map<number, number>();

  private stores = new Map<string, ComponentStore<unknown>>();

  createEntity(): number {
    const e = this.nextEntity++;
    this.entityIndex.set(e, this.entities.length);
    this.entities.push(e);
    return e;
  }

  destroyEntity(entity: number): void {
    const idx = this.entityIndex.get(entity);
    if (idx === undefined) return;
    const last = this.entities.length - 1;
    const swapped = this.entities[last];
    this.entities[idx] = swapped;
    this.entityIndex.set(swapped, idx);
    this.entities.pop();
    this.entityIndex.delete(entity);
    for (const store of this.stores.values()) this.removeIfPresent(store, entity);
  }

  defineComponent<T>(name: string): ComponentStore<T> {
    if (this.stores.has(name)) throw new Error(`component "${name}" already defined`);
    const store: ComponentStore<T> = { set: new SparseSet(), data: [] };
    this.stores.set(name, store as ComponentStore<unknown>);
    return store;
  }

  component<T>(name: string): ComponentStore<T> {
    return this.stores.get(name) as ComponentStore<T>;
  }

  add<T>(store: ComponentStore<T>, entity: number, value: T): void {
    if (store.set.has(entity)) {
      store.data[store.set.indexOf(entity)] = value;
      return;
    }
    store.set.add(entity);
    // keep `data` aligned with the dense array; the appended slot is last
    (store.data as T[]).push(value);
  }

  remove<T>(store: ComponentStore<T>, entity: number): void {
    const idx = store.set.indexOf(entity);
    if (idx === NO_INDEX) return;
    // move the last payload into the removed slot before the set swaps indices
    const last = store.set.size - 1;
    (store.data as T[])[idx] = (store.data as T[])[last];
    (store.data as T[]).pop();
    store.set.remove(entity);
  }

  get<T>(store: ComponentStore<T>, entity: number): T {
    return store.data[store.set.indexOf(entity)];
  }

  has<T>(store: ComponentStore<T>, entity: number): boolean {
    return store.set.has(entity);
  }

  private removeIfPresent<T>(store: ComponentStore<T>, entity: number): void {
    this.remove(store, entity);
  }
}

