import type { ComponentStore, World } from "./world.js";

/**
 * Iterate all entities owning every given component with packed dense arrays.
 * The callback may safely enqueue removals; applyDeferred runs them after
 * iteration so counts and indices stay exact during traversal.
 */
export function each<A>(
  world: World,
  a: ComponentStore<A>,
  fn: (entity: number, av: A) => void,
): void {
  const { dense } = a.set;
  const da = a.data;
  for (let i = dense.length - 1; i >= 0; i--) {
    fn(dense[i], da[i]);
  }
}

