import { World } from "./world.js";
import type { ComponentStore } from "./world.js";

export interface Position {
  x: number;
  y: number;
}
export interface Velocity {
  vx: number;
  vy: number;
}

export interface Scene {
  world: World;
  position: ComponentStore<Position>;
  velocity: ComponentStore<Velocity>;
}

/** Deterministic PRNG (mulberry32) so the fixture is reproducible. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const ENTITY_COUNT = 100_000;
export const BOTH_FRACTION = 0.6;
export const SEED = 1337;

/**
 * Spawn ENTITY_COUNT entities; each gets Position, and exactly
 * floor(ENTITY_COUNT * BOTH_FRACTION) also get Velocity.
 */
export function buildScene(
  entityCount = ENTITY_COUNT,
  bothFraction = BOTH_FRACTION,
  seed = SEED,
): { scene: Scene; bothEntities: number[] } {
  const world = new World();
  const position = world.defineComponent<Position>("position");
  const velocity = world.defineComponent<Velocity>("velocity");
  const rand = mulberry32(seed);

  const bothEntities: number[] = [];
  for (let i = 0; i < entityCount; i++) {
    const e = world.createEntity();
    world.add(position, e, { x: rand() * 1000, y: rand() * 1000 });
    if (i < Math.floor(entityCount * bothFraction)) {
      world.add(velocity, e, { vx: rand() * 10 - 5, vy: rand() * 10 - 5 });
      bothEntities.push(e);
    }
  }
  return { scene: { world, position, velocity }, bothEntities };
}

/** Movement system: p += v * dt for every entity with both components. */
export function movementSystem(scene: Scene, dt: number): void {
  const { position, velocity } = scene;
  const dense = velocity.set.dense; // entities that have Velocity (all also have Position)
  const pos = position.data;
  const vel = velocity.data;
  for (let i = dense.length - 1; i >= 0; i--) {
    const pi = position.set.indexOf(dense[i]);
    pos[pi].x += vel[i].vx * dt;
    pos[pi].y += vel[i].vy * dt;
  }
}

/**
 * Removal system demonstrating deferred mutation: enqueues every entity whose
 * speed exceeds maxSpeed; the caller applies the queue after iteration.
 */
export function collectFastRemovals(scene: Scene, maxSpeed: number): number[] {
  const queue: number[] = [];
  const { position, velocity } = scene;
  const dense = velocity.set.dense;
  for (let i = dense.length - 1; i >= 0; i--) {
    const v = velocity.data[i];
    if (Math.hypot(v.vx, v.vy) > maxSpeed) queue.push(dense[i]);
  }
  return queue;
}

/** Remove a Velocity component (not the entity itself). */
export function applyRemovals(scene: Scene, queue: number[]): void {
  for (const e of queue) scene.world.remove(scene.velocity, e);
}

