    hasVelocity = i < Math.floor(ENTITY_COUNT * BOTH_FRACTION);
    if (hasVelocity) {
      vx = rand() * 10 - 5;
      vy = rand() * 10 - 5;
    }
  }
  if (!hasVelocity) return null; // position-only entity: never moves
  return { x: x + vx * DT * FRAMES, y: y + vy * DT * FRAMES };
}

describe("sparse-set ECS", () => {
  const { scene, bothEntities } = buildScene();
  const { world, position, velocity } = scene;

  it("spawns the fixture with exact component counts", () => {
    expect(world.entities.length).toBe(ENTITY_COUNT);
    expect(position.set.size).toBe(ENTITY_COUNT);
    expect(velocity.set.size).toBe(Math.floor(ENTITY_COUNT * BOTH_FRACTION)); // 60_000
  });

  it("has/get are consistent and O(1) membership is correct", () => {
    expect(world.has(position, 0)).toBe(true);
    expect(world.has(velocity, 0)).toBe(true);
    const posOnly = ENTITY_COUNT - 1; // last entity never got Velocity
    expect(world.has(position, posOnly)).toBe(true);
    expect(world.has(velocity, posOnly)).toBe(false);
    // dense payloads stay aligned with sparse indices
    const idx = velocity.set.indexOf(bothEntities[123]);
    expect(velocity.data[idx]).toBe(world.get(velocity, bothEntities[123]));
  });

  it("movement over 100 frames matches hand-computed values for 5 seeded entities", () => {
    for (let f = 0; f < FRAMES; f++) movementSystem(scene, DT);

    const picks = [0, 12345, 4321, 59999, 7777];
    for (const i of picks) {
      const e = bothEntities[i];
      const expected = referencePosition(i);
      expect(expected).not.toBeNull();
      const p = world.get(position, e);
      expect(p.x).toBeCloseTo(expected!.x, 9);
      expect(p.y).toBeCloseTo(expected!.y, 9);
    }

    // a position-only entity must not have moved at all
    const still = world.get(position, ENTITY_COUNT - 1);
    const seedRand = mulberry32(SEED);
    let lx = 0;
    let ly = 0;
    for (let i = 0; i < ENTITY_COUNT; i++) {
      lx = seedRand() * 1000;
      ly = seedRand() * 1000;
      if (i < Math.floor(ENTITY_COUNT * BOTH_FRACTION)) {
        seedRand();
        seedRand();
      }
    }
    expect(still.x).toBe(lx);
    expect(still.y).toBe(ly);
  });

  it("deferred removal during iteration leaves counts and data exact", () => {
    const beforeVel = velocity.set.size;
    const beforePos = position.set.size;

    // System iterating Position x Velocity enqueues removals instead of
    // mutating mid-iteration...
    const queue: number[] = [];
    const dense = velocity.set.dense;
    for (let i = dense.length - 1; i >= 0; i--) {
      const v = world.get(velocity, dense[i]);
      if (Math.abs(v.vx) > 4.9) queue.push(dense[i]);
    }
    expect(queue.length).toBeGreaterThan(0);

    // ...then applies them once traversal finished.
    applyRemovals(scene, queue);

    expect(velocity.set.size).toBe(beforeVel - queue.length);
    expect(position.set.size).toBe(beforePos); // only Velocity was stripped
    for (const e of queue) {
      expect(world.has(velocity, e)).toBe(false);
      expect(world.has(position, e)).toBe(true);
    }
    // survivors keep their exact payloads despite swap-removal churn
    for (let k = 0; k < 500; k++) {
      const e = bothEntities[(k * 97) % bothEntities.length];
      if (world.has(velocity, e)) {
        const expected = referencePosition(bothEntities.indexOf(e));
        if (expected) {
          const p = world.get(position, e);
          expect(p.x).toBeCloseTo(expected.x, 9);
        }
      }
    }

    // full entity destruction also keeps every store consistent
    const victim = queue[0];
    const velBeforeDestroy = velocity.set.size;
    world.destroyEntity(victim);
    expect(world.has(position, victim)).toBe(false);
    expect(velocity.set.size).toBe(velBeforeDestroy);
  });
});

